mapper.select:
SELECT p.IMG AS img, p.SORT_NO AS sortNo, p.GRP_SEQ AS grpSeq, g.GRP_DT AS grpDt, ISNULL(g.TITLE,'') AS title, ISNULL(g.REG_USER,'') AS regUser
  FROM TBL_PHOTO p JOIN TBL_PHOTO_GRP g ON g.GRP_SEQ = p.GRP_SEQ AND g.COMP_CD = p.COMP_CD
 WHERE p.COMP_CD = #{compCd} AND p.PHOTO_SEQ = #{photoSeq}

SELECT ISNULL(p.THUMB, p.IMG) AS img
  FROM TBL_PHOTO p
 WHERE p.COMP_CD = #{compCd} AND p.PHOTO_SEQ = #{photoSeq}
